import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Formatter as a Production Pipeline","description":"","frontmatter":{"title":"Formatter as a Production Pipeline","type":"adr","date":"2026-09-08T00:00:00.000Z","status":"proposed","status_note":"Proposed — formatter stages are data; `NodeEmitter` is the swap point."},"headers":[],"relativePath":"handl/project/adrs/0095-formatter-as-production-pipeline.md","filePath":"vendored/handl/project/adrs/0095-formatter-as-production-pipeline.md"}'),a={name:`handl/project/adrs/0095-formatter-as-production-pipeline.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0095-formatter-as-a-production-pipeline" tabindex="-1">ADR-0095: Formatter as a Production Pipeline <a class="header-anchor" href="#adr-0095-formatter-as-a-production-pipeline" aria-label="Permalink to “ADR-0095: Formatter as a Production Pipeline”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Crate boundary</strong>: the formatter keeps the abstraction/engine split — contract types and the formatting trait in one crate, the implementation in another.</li><li><strong>Pipeline and stage contracts</strong>: parse → layout → emit, with stable contracts between stages; a stage can be replaced without touching its neighbours.</li><li><strong>Rule seam</strong>: <code>FormattingRule</code> is replaceable and composable; formatting rules are data, not <code>kind ==</code> branches.</li><li><strong>Config seam</strong>: formatting options are resolved once and passed as a config value, not read from globals.</li><li><strong>Engine seam</strong>: <code>NodeEmitter</code> stays the swap point for a different layout strategy.</li><li><strong>Generic capability</strong>: <code>platform/format.rs</code> is either wired to the real engine or retired explicitly — no dead second path.</li><li><strong>Language-as-data style</strong>: no hardcoded kind strings; the formatter reads grammar roles and shapes.</li><li><strong>Performance</strong>: parallel <code>--write</code>/<code>--check</code> across files and a stage-boundary cache keyed on content hash.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The formatter was a monolithic pass with hardcoded kinds and a second, dead <code>FormatEngine</code> path, so a layout change touched the whole formatter. Stable stage contracts and a rule seam make formatting data and the engine swappable.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep one monolithic pass</strong> — the coupling this removes.</li><li><strong>Two format engines</strong> — wire the capability or retire it.</li><li><strong>Hardcoded kind strings</strong> — roles and shapes come from grammar data.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Stages and rules are replaceable; the emitter is the swap point.</li><li>Parallel file formatting and stage caching become possible.</li><li>One capability path, not two.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>engine-fmt/</code> — the formatter engine and stage contracts.</li><li><code>plugin-engine-fmt/</code> — the contract types (if separate).</li><li>Formatter tests and the idempotence gate.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Crate boundary, pipeline contracts, seams and performance notes: +<a href="./../design/0095-formatter-as-production-pipeline.html"><code>design/0095-formatter-as-production-pipeline.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};